(4764044, 687708, 34255, '<td valign="top">Great colors and perspective.</td>', 'Great colors and perspective.', '2008-06-11 13:30:26.000000', NULL, 1),
(4764048, 687471, 63398, '<td valign="top">Excellent image, and very well done example without using the tired, overhammered B&amp;W harshness. Love the definition &amp; detail, especially the clarity of a busy subject......the contrast examples abound. I''m most impressed with this entry! Brave and well executed. Good luck! 9</td>', 'Excellent image, and very well done example without using the tired, overhammered B&W harshness. Love the definition & detail, especially the clarity of a busy subject......the contrast examples abound. I''m most impressed with this entry! Brave and well executed. Good luck! 9', '2008-06-11 13:32:58.000000', NULL, 1),
(4764051, 687483, 63398, '<td valign="top">I don''t see the soup tie-in, but a nice shot nonetheless. 7</td>', 'I don''t see the soup tie-in, but a nice shot nonetheless. 7', '2008-06-11 13:33:36.000000', NULL, 1),
(4764053, 687774, 63398, '<td valign="top">Nice! Love the whiskers!</td>', 'Nice! Love the whiskers!', '2008-06-11 13:34:10.000000', NULL, 1),
(4764054, 687526, 63398, '<td valign="top">I think this is pretty good, but I also see it as a compromise by losing color to gain contrast. I only mention this because I tried a very similar idea and couldn''t get it to where I thought it would work......and I have the 4.5 to prove it! LOL!!! 5</td>', 'I think this is pretty good, but I also see it as a compromise by losing color to gain contrast. I only mention this because I tried a very similar idea and couldn''t get it to where I thought it would work......and I have the 4.5 to prove it! LOL!!! 5', '2008-06-11 13:35:50.000000', NULL, 1),
(4764059, 687576, 63398, '<td valign="top">Pretty good job of getting the contrast without blowing out. I''m undecided on the tilt.....not my taste.</td>', 'Pretty good job of getting the contrast without blowing out. I''m undecided on the tilt.....not my taste.', '2008-06-11 13:39:48.000000', NULL, 1),
