(4765543, 687528, 74588, '<td valign="top">dont know so much about the contrast but it talks   7</td>', 'dont know so much about the contrast but it talks   7', '2008-06-12 05:20:52.000000', NULL, 1),
(4765545, 687062, 74588, '<td valign="top">i must say this is very good     9</td>', 'i must say this is very good     9', '2008-06-12 05:22:12.000000', NULL, 1),
(4765546, 687802, 57229, '<td valign="top">You''ve contrasted a light foreground with a dark background, but there are essentially too many mid tones in evidence to call this a high contrast picture.</td>', 'You''ve contrasted a light foreground with a dark background, but there are essentially too many mid tones in evidence to call this a high contrast picture.', '2008-06-12 05:30:49.000000', NULL, 1),
(4765549, 687711, 57229, '<td valign="top">There''s a lot of contrast in there, but I wouldn''t call this a high contrast picture. Too many mid tones and non-primary colours. I think it could probably be cranked into a genuine high contrast condition with some legal post processing, but I have to admit it might not look very nice :)</td>', 'There''s a lot of contrast in there, but I wouldn''t call this a high contrast picture. Too many mid tones and non-primary colours. I think it could probably be cranked into a genuine high contrast condition with some legal post processing, but I have to admit it might not look very nice :)', '2008-06-12 05:34:32.000000', NULL, 1),
(4765551, 687483, 57229, '<td valign="top">All you had to do was drag the slider on the Brightness/Contrast thingy and you would have had a high contrast picture here. It probably looks nicer like this, but what can you do?</td>', 'All you had to do was drag the slider on the Brightness/Contrast thingy and you would have had a high contrast picture here. It probably looks nicer like this, but what can you do?', '2008-06-12 05:37:02.000000', NULL, 1),
(4765553, 687633, 57229, '<td valign="top">Nearly no black and nearly no white...</td>', 'Nearly no black and nearly no white...', '2008-06-12 05:37:51.000000', NULL, 1),
(4765555, 687891, 57229, '<td valign="top">With the possible exception of the sky, I''d say this was all mid tones.</td>', 'With the possible exception of the sky, I''d say this was all mid tones.', '2008-06-12 05:38:49.000000', NULL, 1),
(4765564, 687297, 88718, '<td valign="top">This shot really needs more light on the snail to give it more of a 3D shape</td>', 'This shot really needs more light on the snail to give it more of a 3D shape', '2008-06-12 05:49:13.000000', NULL, 1),
(4765565, 687248, 88718, '<td valign="top">I like the grainy, newspaper look.</td>', 'I like the grainy, newspaper look.', '2008-06-12 05:49:34.000000', NULL, 1),
(4765566, 687509, 88718, '<td valign="top">Indeed, the spider is a bit too itsy bitsy in this photograph. A differing crop may have helped</td>', 'Indeed, the spider is a bit too itsy bitsy in this photograph. A differing crop may have helped', '2008-06-12 05:50:29.000000', NULL, 1),
(4765567, 687728, 88718, '<td valign="top">Classic cloud shot with excellent movelment.</td>', 'Classic cloud shot with excellent movelment.', '2008-06-12 05:51:07.000000', NULL, 1),
