(4765569, 686549, 88718, '<td valign="top">Great colours. Looks inviting and threatening at the same time.</td>', 'Great colours. Looks inviting and threatening at the same time.', '2008-06-12 05:52:18.000000', NULL, 1),
(4765570, 687534, 88718, '<td valign="top">This is a classic shot in its genre. Perhaps the angle is too oblique thus the woman and the rails compete.</td>', 'This is a classic shot in its genre. Perhaps the angle is too oblique thus the woman and the rails compete.', '2008-06-12 05:53:28.000000', NULL, 1),
(4765571, 687708, 88718, '<td valign="top">Not sure how you arrived at these colours with basic editing but its a great shot anyway</td>', 'Not sure how you arrived at these colours with basic editing but its a great shot anyway', '2008-06-12 05:54:23.000000', NULL, 1),
(4765572, 687704, 88718, '<td valign="top">Slightly off center but a great composition</td>', 'Slightly off center but a great composition', '2008-06-12 05:55:08.000000', NULL, 1),
(4765573, 687510, 88718, '<td valign="top">Great colours in the sky. I really like this one</td>', 'Great colours in the sky. I really like this one', '2008-06-12 05:56:35.000000', NULL, 1),
(4765574, 687504, 88718, '<td valign="top">Well chosen shot and well executed.</td>', 'Well chosen shot and well executed.', '2008-06-12 05:57:44.000000', NULL, 1),
(4765576, 687854, 88718, '<td valign="top">Amazing colours. The crop puts the bird a bit too low in the picture and a bit to centered. I guess you wanted to include the lighter stripe at the top. A tough call.</td>', 'Amazing colours. The crop puts the bird a bit too low in the picture and a bit to centered. I guess you wanted to include the lighter stripe at the top. A tough call.', '2008-06-12 05:59:24.000000', NULL, 1),
(4765581, 686053, 57229, '<td valign="top">Lovely picture, magnificent beast. Had this been high contrast then there would be less grey and more black and white. It might even have enhanced the impact.</td>', 'Lovely picture, magnificent beast. Had this been high contrast then there would be less grey and more black and white. It might even have enhanced the impact.', '2008-06-12 06:11:01.000000', NULL, 1),
(4765583, 687781, 57229, '<td valign="top">Heh. Take down the magenta and crank the blacks and you might have had something here.</td>', 'Heh. Take down the magenta and crank the blacks and you might have had something here.', '2008-06-12 06:13:49.000000', NULL, 1),
(4765584, 685982, 57229, '<td valign="top">You could have been brave and cranked the contrast, but it''s getting there...</td>', 'You could have been brave and cranked the contrast, but it''s getting there...', '2008-06-12 06:15:24.000000', NULL, 1),
(4765585, 686529, 57229, '<td valign="top">I do not see high contrast (predominance of black and white with very few mid tones) in this.</td>', 'I do not see high contrast (predominance of black and white with very few mid tones) in this.', '2008-06-12 06:16:25.000000', NULL, 1),
(4765586, 687863, 57229, '<td valign="top">Poor choice of subject, IMO. The quality of this picture is almost entirely dependent on the graduation of mid tones in the skin, making any hgigh contrast black and/or white elements incidental and/or irrelevant. Had you made a high contrast picture of it then she probably would have looked less pretty...</td>', 'Poor choice of subject, IMO. The quality of this picture is almost entirely dependent on the graduation of mid tones in the skin, making any hgigh contrast black and/or white elements incidental and/or irrelevant. Had you made a high contrast picture of it then she probably would have looked less pretty...', '2008-06-12 06:19:36.000000', NULL, 1),
(4765592, 687528, 88718, '<td valign="top">At least it''s not a lemon....</td>', 'At least it''s not a lemon....', '2008-06-12 07:04:48.000000', NULL, 1),
(4765593, 687185, 88718, '<td valign="top">Very nice toning. A good choice.</td>', 'Very nice toning. A good choice.', '2008-06-12 07:05:15.000000', NULL, 1),
